package api

var sswCurriculumRoadTransportCautionsEnglish = map[examSSWEnglishKey]string{
	{field: "ssw.caution", source: `Jangan berasumsi bahwa jadwal lama masih berlaku ketika ada pemberitahuan baru.`}:                     `Do not assume the old schedule still applies when a new notice has been issued.`,
	{field: "ssw.caution", source: `Jangan melanjutkan dengan mengandalkan kopi atau perkiraan sendiri bila merasa tidak aman.`}:          `If you feel unsafe, do not rely on coffee or your own estimate to keep driving.`,
	{field: "ssw.caution", source: `Jangan melewati tanda kerusakan atau menyentuh peralatan yang belum diizinkan.`}:                      `Do not ignore a fault indicator or handle equipment without authorization.`,
	{field: "ssw.caution", source: `Jangan melihat atau mengetik perangkat saat perhatian harus tertuju pada jalan.`}:                     `Do not look at or type on a device when your attention must be on the road.`,
	{field: "ssw.caution", source: `Jangan menandai pengiriman atau layanan selesai jika masih ada barang atau masalah terbuka.`}:         `Do not mark a delivery or service as complete while goods or issues remain outstanding.`,
	{field: "ssw.caution", source: `Jangan mengalihkan tujuan atau meninggalkan muatan tanpa instruksi dan catatan.`}:                     `Do not change the destination or leave cargo without instructions and a record.`,
	{field: "ssw.caution", source: `Jangan mengambil alih kategori kendaraan atau tugas yang belum menjadi penugasan Anda.`}:              `Do not take on a vehicle category or duty that has not been assigned to you.`,
	{field: "ssw.caution", source: `Jangan menganggap alamat pada layar benar bila penumpang menyebut tujuan lain.`}:                      `Do not assume the address on the screen is correct if the passenger gives another destination.`,
	{field: "ssw.caution", source: `Jangan mengubah jumlah, label, atau cara pengikatan berdasarkan perkiraan.`}:                          `Do not change quantities, labels, or securing methods based on a guess.`,
	{field: "ssw.caution", source: `Jangan menjanjikan diagnosis atau meninggalkan penumpang tanpa arahan yang sesuai.`}:                  `Do not promise a diagnosis or leave a passenger without appropriate guidance.`,
	{field: "ssw.caution", source: `Jangan menjanjikan waktu berangkat atau memulai kembali sebelum mendapat arahan.`}:                    `Do not promise a departure time or resume service before receiving instructions.`,
	{field: "ssw.caution", source: `Jangan mulai bergerak ketika penumpang masih berada di area pintu atau belum siap menurut prosedur.`}: `Do not move while a passenger is still in the doorway or not yet ready under procedure.`,
}
